Send Freeform Message.code:
// Send a freeform text message via the WhatsApp Business API.
// Only allowed within the 24-hour customer service window.
request('POST', 'messages', {
  messaging_product: 'whatsapp',
  recipient_type: 'individual',
  to:   $.data.toPhone,        // E.164, no '+' (e.g. '254712345678')
  type: 'text',
  text: { body: $.data.body },
});

Send Media Message.code:
// Send a media attachment. `type` is one of image | video | document | audio.
request('POST', 'messages', {
  messaging_product: 'whatsapp',
  recipient_type: 'individual',
  to:   $.data.toPhone,
  type: 'image',
  image: {
    // Either a public URL...
    link: $.data.imageUrl,
    // ...or `id` referencing a previously uploaded media id.
    caption: $.data.caption,
  },
});

Send Template Message.code:
// Send an approved WhatsApp template message.
request('POST', 'messages', {
  messaging_product: 'whatsapp',
  recipient_type: 'individual',
  to:   $.data.toPhone,
  type: 'template',
  template: {
    name: 'hello_world',
    language: { code: 'en_US', policy: 'deterministic' },
    // Template body variables, if your template uses {{1}}, {{2}}, ...
    // components: [{
    //   type: 'body',
    //   parameters: [{ type: 'text', text: $.data.firstName }],
    // }],
  },
});

Create QR Code Deep Link.code:
// Create a QR code that opens a chat with this business number,
// prefilled with a message (max 140 characters).
request('POST', 'message_qrdls', {
  prefilled_message: 'Register for the vaccination drive',
  generate_qr_image: 'PNG', // or 'SVG'
});
// state.data.deep_link_url and state.data.qr_image_url hold the link and image.

Block User.code:
// Block one or more users by phone number or WhatsApp ID.
request('POST', 'block_users', {
  messaging_product: 'whatsapp',
  block_users: [{ user: $.data.phone }],
});

Update Business Profile.code:
// Update the profile users see when they open the chat.
request('POST', 'whatsapp_business_profile', {
  messaging_product: 'whatsapp',
  about: 'Appointment reminders and test results.',
  email: 'hello@clinic.example.org',
  vertical: 'HEALTH',
});

Enable Cart and Catalog.code:
// Commerce settings are set with query parameters, not a body.
request('POST', 'whatsapp_commerce_settings', undefined, {
  query: { is_cart_enabled: true, is_catalog_visible: true },
});

Get Phone Number Status.code:
// An empty path addresses the phone number node itself.
request('GET', '', undefined, {
  query: { fields: 'display_phone_number,verified_name,quality_rating' },
});

Get Business Profile.code:
request('GET', 'whatsapp_business_profile', undefined, {
  query: { fields: 'about,address,description,email,websites,vertical' },
});
// state.data.data[0] holds the profile.
